import{_ as a,o,c as t,a2 as c}from"./chunks/framework.BkO3HzvX.js";const m=JSON.parse('{"title":"Neony API reference","description":"","frontmatter":{},"headers":[],"relativePath":"api/index.md","filePath":"api/index.md"}'),i={name:"api/index.md"};function n(r,e,d,l,s,p){return o(),t("div",null,[...e[0]||(e[0]=[c('<h1 id="neony-api-reference" tabindex="-1">Neony API reference <a class="header-anchor" href="#neony-api-reference" aria-label="Permalink to &quot;Neony API reference&quot;">​</a></h1><p>The reference is split into paired chapters. Each chapter covers one area with short signatures, parameters, return values, edge cases, and a small example; long-form explanations live in the guides. API symbols, import paths, commands, and example filenames stay in English in both language versions so code can be copied directly.</p><h2 id="chapters" tabindex="-1">Chapters <a class="header-anchor" href="#chapters" aria-label="Permalink to &quot;Chapters&quot;">​</a></h2><ul><li><a href="/neony/api/core.html">Core</a> — <code>NeonApplication</code>, <code>launch</code>, <code>Config</code> / <code>WindowConfig</code> / <code>WebViewConfig</code>, <code>Page</code>, lifecycle, multi-window, navigation policies, <code>Tray</code>.</li><li><a href="/neony/api/components.html">Components</a> — form controls, text &amp; tabs, overlays &amp; feedback, content components, and the <code>Reorder</code> drag-and-reorder component.</li><li><a href="/neony/api/layout-chrome.html">Layout &amp; chrome</a> — <code>VStack</code> / <code>HStack</code> / <code>Flex</code> / <code>Separator</code> / <code>GlassPanel</code>, <code>TitleBar</code>, <code>Sidebar</code> / <code>Pane</code> / <code>SidebarGroup</code>, <code>Tree</code>, <code>List</code>, <code>DataTable</code>, <code>Icon</code>.</li><li><a href="/neony/api/dom-css.html">DOM &amp; CSS</a> — <code>Color</code>, <code>Styles</code>, <code>DomEvent</code>, raw HTML elements, and the low-level drag primitive.</li><li><a href="/neony/api/reactive.html">Reactivity</a> — <code>Signal</code>, <code>Computed</code>, <code>effect</code> / <code>Effect</code>, <code>untrack</code>, <code>SharedSignal</code>, declarative bindings, <code>bind_value</code>, dirty-subtree tracking.</li><li><a href="/neony/api/platform-i18n.html">Platform &amp; i18n</a> — internationalization, theming, and the platform-native surfaces (window controls, native file dialogs, system tray).</li></ul><h2 id="stability" tabindex="-1">Stability <a class="header-anchor" href="#stability" aria-label="Permalink to &quot;Stability&quot;">​</a></h2><p>Neony is pre-beta. Some names still carry deprecated aliases (e.g. <code>active_key</code> → <code>selected_key</code>); the chapters note them inline. See the project&#39;s <a href="https://github.com/HarcicYang/Neony/blob/b744352/CHANGELOG.md" target="_blank" rel="noreferrer">CHANGELOG</a> for the per-version story.</p><p>For an exact signature not yet split out, the previous monolithic entry is retained temporarily at <a href="/neony/api/"><code>api.en.md</code></a> as a stable link target while readers and external links migrate.</p>',7)])])}const f=a(i,[["render",n]]);export{m as __pageData,f as default};
